+++ b/packages/checkout/src/checkout.ts
@@ -1,9 +1,12 @@
-import { isKnownCode, resolvePromo } from "@acme/pricing";
+import { resolvePromoStatus } from "@acme/pricing";
 import type { Cart } from "@acme/pricing";

 export class PromoError extends Error {
-  constructor(public readonly code: string) {
-    super(`Unknown promo code: ${code}`);
+  constructor(
+    public readonly code: string,
+    public readonly reason: "unknown" | "expired" = "unknown",
+  ) {
+    super(reason === "expired" ? `EXPIRED promo code: ${code}` : `Unknown promo code: ${code}`);
     this.name = "PromoError";
   }
 }
@@ -15,11 +18,9 @@ export class PromoError extends Error {
  * to the lookup the code is valid and `resolvePromo` always resolves.
  */
 export function applyPromo(cart: Cart, code: string): number {
-  if (!isKnownCode(code)) {
-    throw new PromoError(code);
-  }
-
-  const promo = resolvePromo(code);
+  const resolution = resolvePromoStatus(code);
+  if (resolution.status !== "valid") throw new PromoError(code, resolution.status);
+  const promo = resolution.promo;

   return Math.round(cart.subtotal * (1 - promo!.discount) * 100) / 100;
 }
