diff --git a/packages/pricing/src/promo.ts b/packages/pricing/src/promo.ts
index 091d10e..8124f24 100644
--- a/packages/pricing/src/promo.ts
+++ b/packages/pricing/src/promo.ts
@@ -18,6 +18,17 @@ export function isKnownCode(code: string): boolean {
   return CATALOG.some((p) => p.code === code.trim().toUpperCase());
 }

+export type PromoResolution =
+  | { status: "valid"; promo: Promo }
+  | { status: "expired" | "unknown"; promo: null };
+
+/** Resolve a code while preserving why no active promotion was returned. */
+export function resolvePromoStatus(code: string): PromoResolution {
+  const promo = resolvePromo(code);
+  if (promo) return { status: "valid", promo };
+  return { status: isKnownCode(code) ? "expired" : "unknown", promo: null };
+}
